import { lazy, Suspense } from "react";
import ErrorBoundary from "./ErrorBoundary";

// Remote is provided at runtime by the federation runtime
const Checkout = lazy(() => import("checkout/CheckoutApp"));

function App() {
  return (
    <ErrorBoundary fallback={<p>Checkout is unavailable.</p>}>
      <Suspense fallback={<p>Loading checkout...</p>}>
        <Checkout />
      </Suspense>
    </ErrorBoundary>
  );
}

// The shell no longer bundles Checkout: it is fetched from the
// remote's own deployment, so every team ships on its own schedule.

// webpack.config.js — the shell and every remote agree on one React
new ModuleFederationPlugin({
  name: "shell",
  remotes: {
    checkout: "checkout@https://checkout.example.com/remoteEntry.js",
  },
  shared: {
    react: { singleton: true, requiredVersion: "^18.0.0" },
    "react-dom": { singleton: true, requiredVersion: "^18.0.0" },
  },
});

// A second copy of React in the page breaks hooks and events,
// so `singleton: true` is not optional — it is a correctness
// constraint, and a version mismatch must fail loudly.
